insert into public.site_text (key, section, label, pt, en, multiline, allows_html, sort_order) values ('meta.description', 'Metadados', 'Descrição para buscadores', 'Professor do Magistério Superior na Universidade Federal do Oeste do Pará. Doutor em Computação Aplicada pelo INPE. Pesquisa em inteligência artificial, ciência de dados e nowcasting de sistemas precipitantes.', 'Assistant Professor at the Federal University of Western Pará, Brazil. PhD in Applied Computing from INPE. Research in artificial intelligence, data science and nowcasting of precipitating systems.', true, false, 1);
