insert into public.site_text (key, section, label, pt, en, multiline, allows_html, sort_order) values ('about.lede', 'Perfil', null, 'Formação em computação aplicada com atuação na interface entre inteligência artificial, ciência de dados e monitoramento ambiental.', 'Trained in applied computing, working at the interface of artificial intelligence, data science and environmental monitoring.', true, false, 23);
insert into public.site_text (key, section, label, pt, en, multiline, allows_html, sort_order) values ('about.p1', 'Perfil', 'Biografia — parágrafo 1', '<strong>Helvecio Bezerra Leal Neto</strong> é Professor do Magistério Superior na Universidade Federal do Oeste do Pará (UFOPA), lotado no Instituto de Engenharia e Geociências, onde atua no Bacharelado em Inteligência Artificial. É Doutor e Mestre em Computação Aplicada pelo Instituto Nacional de Pesquisas Espaciais (INPE), Bacharel em Ciência da Computação pela UFOPA e Tecnólogo em Redes de Computadores pelo IESPES.', '<strong>Helvecio Bezerra Leal Neto</strong> is an Assistant Professor at the Federal University of Western Pará (UFOPA), based at the Institute of Engineering and Geosciences, where he teaches in the BSc programme in Artificial Intelligence. He holds a PhD and an MSc in Applied Computing from the National Institute for Space Research (INPE), a BSc in Computer Science from UFOPA and a technologist degree in Computer Networks from IESPES.', true, true, 24);
insert into public.site_text (key, section, label, pt, en, multiline, allows_html, sort_order) values ('about.p2', 'Perfil', 'Biografia — parágrafo 2', 'Sua pesquisa concentra-se em ciência de dados e inteligência artificial aplicadas ao monitoramento ambiental, com ênfase no rastreio automático e na previsão de curtíssimo prazo (<em>nowcasting</em>) de sistemas precipitantes. É autor principal do <strong>pyForTraCC</strong>, biblioteca Python de código aberto para identificação, rastreio e previsão de aglomerados configuráveis, sucessora modernizada do algoritmo ForTraCC desenvolvido no INPE.', 'His research focuses on data science and artificial intelligence applied to environmental monitoring, with emphasis on the automatic tracking and very short-term forecasting (<em>nowcasting</em>) of precipitating systems. He is the lead author of <strong>pyForTraCC</strong>, an open-source Python library for identifying, tracking and forecasting configurable clusters — a modernised successor to the ForTraCC algorithm developed at INPE.', true, true, 25);
insert into public.site_text (key, section, label, pt, en, multiline, allows_html, sort_order) values ('about.p3', 'Perfil', 'Biografia — parágrafo 3', 'Integra os grupos de pesquisa SInApSE/INPE — Aplicações de Inteligência Artificial e Big Data em Atmosfera e Espaço — e LABREN/INPE, laboratório de modelagem e estudos de recursos renováveis de energia. Sua produção abrange rastreio de sistemas precipitantes na Bacia Amazônica, padrões espaço-temporais de descargas atmosféricas, redes complexas aplicadas a precipitação extrema e radiação ultravioleta solar.', 'He is a member of the SInApSE/INPE research group — Applications of Artificial Intelligence and Big Data in Atmosphere and Space — and of LABREN/INPE, the laboratory for modelling and studies of renewable energy resources. His published work spans the tracking of precipitating systems over the Amazon Basin, spatio-temporal lightning patterns, complex networks applied to extreme precipitation, and solar ultraviolet radiation.', true, false, 26);
