insert into public.site_text (key, section, label, pt, en, multiline, allows_html, sort_order) values ('footer.tagline', 'Rodapé', 'Resumo no rodapé', 'Professor do Magistério Superior no Instituto de Engenharia e Geociências da Universidade Federal do Oeste do Pará. Pesquisa em inteligência artificial e ciência de dados aplicadas ao monitoramento ambiental.', 'Assistant Professor at the Institute of Engineering and Geosciences, Federal University of Western Pará. Research in artificial intelligence and data science applied to environmental monitoring.', true, false, 104);
