insert into public.research_areas (sort_order, title_pt, title_en, body_pt, body_en) values (0, 'Nowcasting e rastreio de sistemas precipitantes', 'Nowcasting and tracking of precipitating systems', 'Algoritmos de identificação, associação temporal e previsão de curtíssimo prazo de sistemas convectivos a partir de satélite, radar e produtos globais de precipitação.', 'Algorithms for identification, temporal association and very short-term forecasting of convective systems from satellite, radar and global precipitation products.');
insert into public.research_areas (sort_order, title_pt, title_en, body_pt, body_en) values (1, 'Inteligência artificial aplicada à atmosfera', 'Artificial intelligence for the atmosphere', 'Modelos de aprendizado profundo e de máquina para previsão probabilística de descargas atmosféricas e de eventos severos na Bacia Amazônica.', 'Deep learning and machine learning models for probabilistic forecasting of lightning and severe weather events over the Amazon Basin.');
insert into public.research_areas (sort_order, title_pt, title_en, body_pt, body_en) values (2, 'Ciência de dados geoespaciais', 'Geospatial data science', 'Pipelines escaláveis para aquisição, processamento e vetorização de dados de sensoriamento remoto, com ênfase em séries temporais de larga escala.', 'Scalable pipelines for the acquisition, processing and vectorisation of remote sensing data, with emphasis on large-scale time series.');
insert into public.research_areas (sort_order, title_pt, title_en, body_pt, body_en) values (3, 'Redes complexas e agrupamento', 'Complex networks and clustering', 'Detecção de comunidades e análise de sensibilidade espacial aplicadas a precipitação extrema e à caracterização morfológica de sistemas atmosféricos.', 'Community detection and spatial sensitivity analysis applied to extreme precipitation and to the morphological characterisation of atmospheric systems.');
insert into public.research_areas (sort_order, title_pt, title_en, body_pt, body_en) values (4, 'Segurança da informação', 'Information security', 'Fundamentos de segurança, criptografia, autenticação, auditoria de sistemas e conformidade normativa em ambientes computacionais.', 'Security fundamentals, cryptography, authentication, systems auditing and regulatory compliance in computing environments.');
insert into public.research_areas (sort_order, title_pt, title_en, body_pt, body_en) values (5, 'Software científico aberto', 'Open scientific software', 'Desenvolvimento de bibliotecas reprodutíveis e documentadas para a comunidade de ciências atmosféricas e de dados ambientais.', 'Development of reproducible, well-documented libraries for the atmospheric sciences and environmental data communities.');
