insert into public.software (sort_order, name, stars, repo, docs, featured, desc_pt, desc_en) values (0, 'pyForTraCC', 39, 'https://github.com/fortracc/pyfortracc', 'https://pyfortracc.readthedocs.io', true, 'Biblioteca Python modular e escalável para identificação, rastreio e previsão de aglomerados configuráveis em campos espaço-temporais. Sucessora do algoritmo ForTraCC do INPE, é aplicada ao nowcasting de sistemas precipitantes a partir de dados globais de satélite, radar e produtos de precipitação. Arquitetura dividida em módulos de rastreio e previsão, com extração de características por multi-limiares e vetorização geoespacial dos aglomerados.', 'A modular, scalable Python library for identifying, tracking and forecasting configurable clusters in spatio-temporal fields. Successor to INPE’s ForTraCC algorithm, it is applied to the nowcasting of precipitating systems from global satellite, radar and precipitation products. Its architecture splits into tracking and forecasting modules, with multi-threshold feature extraction and geospatial vectorisation of clusters.');
insert into public.software (sort_order, name, stars, repo, docs, featured, desc_pt, desc_en) values (1, 'goesgcp', 10, 'https://github.com/helvecioneto/goesgcp', null, false, 'Utilitário para download eficiente de dados do satélite GOES a partir do Google Cloud Platform, com recorte espacial, reprojeção e conversão para formatos analíticos.', 'A utility for efficiently downloading GOES satellite data from Google Cloud Platform, with spatial subsetting, reprojection and conversion to analysis-ready formats.');
insert into public.software (sort_order, name, stars, repo, docs, featured, desc_pt, desc_en) values (2, 'metdown', 0, 'https://github.com/helvecioneto/metdown', null, false, 'Biblioteca para download, processamento e padronização de dados meteorológicos de múltiplas fontes em fluxos reprodutíveis.', 'A library for downloading, processing and standardising meteorological data from multiple sources into reproducible workflows.');
insert into public.software (sort_order, name, stars, repo, docs, featured, desc_pt, desc_en) values (3, 'datascience', 22, 'https://github.com/helvecioneto/datascience', null, false, 'Material didático completo da disciplina de Introdução à Ciência de Dados: notebooks, conjuntos de dados e exercícios resolvidos.', 'Complete teaching materials for the Introduction to Data Science course: notebooks, datasets and worked exercises.');
insert into public.software (sort_order, name, stars, repo, docs, featured, desc_pt, desc_en) values (4, 'gldrive', 0, 'https://github.com/helvecioneto/gldrive', null, false, 'Sincronização, upload e download para o Google Drive com semântica semelhante ao scp, voltada a fluxos de trabalho científicos em servidores remotos.', 'scp-like upload, download and synchronisation for Google Drive, aimed at scientific workflows on remote servers.');
insert into public.software (sort_order, name, stars, repo, docs, featured, desc_pt, desc_en) values (5, 'gp5-wc', 14, 'https://github.com/helvecioneto/gp5-wc', '/gp5.html', false, 'Controlador web para o processador de efeitos GP-5 via Web MIDI, com edição de patches diretamente no navegador.', 'A browser-based controller for the GP-5 effects processor over Web MIDI, with patch editing directly in the browser.');
